-- Schema-only candidate. No provider registration, source approval or permission grants.
CREATE TABLE sites_source_heads(source_key TEXT PRIMARY KEY,workspace TEXT NOT NULL,account_id TEXT NOT NULL,identity_json TEXT NOT NULL,source_revision INTEGER NOT NULL,descriptor_hash TEXT NOT NULL,summary_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('READING','IMPORTED','FAILED','QA_BLOCKED','CONFLICT')),attempt_id TEXT NOT NULL,reason TEXT,updated_at TEXT NOT NULL,FOREIGN KEY(workspace,account_id) REFERENCES sites_account_details(workspace,account_id));
CREATE TABLE sites_source_attempts(id TEXT PRIMARY KEY,source_key TEXT NOT NULL REFERENCES sites_source_heads(source_key),source_revision INTEGER NOT NULL,descriptor_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('READING','IMPORTED','FAILED','QA_BLOCKED','CONFLICT')),reason TEXT,created_at TEXT NOT NULL);
-- Bound before media IO; a failed/obsolete intake cannot leave an unguarded review.
CREATE TABLE sites_review_sources(review_id TEXT PRIMARY KEY,source_key TEXT NOT NULL REFERENCES sites_source_heads(source_key),source_revision INTEGER NOT NULL,descriptor_hash TEXT NOT NULL);
CREATE TABLE sites_source_import_receipts(source_key TEXT NOT NULL REFERENCES sites_source_heads(source_key),source_revision INTEGER NOT NULL,descriptor_hash TEXT NOT NULL,review_id TEXT NOT NULL REFERENCES sites_reviews(id),PRIMARY KEY(source_key,source_revision));
